/// Source text of helper libraries that ship next to the embedded gateway
/// server.dart. Kept as plain strings (no imports) so they can also be
/// extracted and exercised with `dart test` outside Flutter; see
/// tool/gateway_test/run.sh.
const String kGatewayAuthDart = r'''
// gateway_auth.dart - generated by the GupTik desktop app. Edits on the node are overwritten.
//
// Authentication for the node gateway:
//   * per-phone bearer tokens `gt1.<id>.<secret>` (only SHA-256(secret) is stored, table gw_devices)
//   * an owner token `gt1.owner.<secret>` for the desktop app (hash in OWNER_TOKEN_SHA256)
//   * short-lived signed anonymous viewer tokens `gv1.<exp>.<nonce>.<sig>` for read-only player routes
//   * GATEWAY_AUTH=audit (default: log what would be denied) or GATEWAY_AUTH=enforce
import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'dart:math';
import 'package:crypto/crypto.dart';
import 'package:postgres/postgres.dart';
import 'package:shelf/shelf.dart';
import 'package:shelf_router/shelf_router.dart';

const String kStorageRoot = '/app/storage';

/// Set from GATEWAY_AUTH at startup; read by handlers that gate private data.
bool gatewayEnforce = false;

// ---------------------------------------------------------------- database

Endpoint dbEndpoint() {
  final pw = Platform.environment['DB_PASSWORD'];
  if (pw == null || pw.isEmpty) {
    throw StateError('DB_PASSWORD is not set. Open the GupTik desktop app so it can finish the node update.');
  }
  return Endpoint(
    host: Platform.environment['DB_HOST'] ?? 'db',
    port: 5432,
    database: 'postgres',
    username: 'postgres',
    password: pw,
  );
}

Future<Connection> openDb() => Connection.open(dbEndpoint(), settings: const ConnectionSettings(sslMode: SslMode.disable));

// ------------------------------------------------------------ storage paths

/// A bare file name inside the storage folder. Rejects separators, `.`/`..`, NUL and empty names.
String safeStorageName(String raw) {
  if (raw.isEmpty ||
      raw.length > 255 ||
      raw == '.' ||
      raw == '..' ||
      raw.contains('/') ||
      raw.contains('\\') ||
      raw.contains('\u0000')) {
    throw const FormatException('invalid file name');
  }
  return raw;
}

/// File inside /app/storage for a client-supplied name; throws FormatException if it would escape.
File storageFile(String name) {
  final f = File('$kStorageRoot/${safeStorageName(name)}');
  if (!f.absolute.path.startsWith('$kStorageRoot/')) throw const FormatException('invalid file name');
  return f;
}

// ------------------------------------------------------------------ tokens

enum Role { owner, device, viewer }

class Principal {
  final Role role;
  final String id;
  final String name;
  const Principal(this.role, this.id, this.name);
  bool get isTrusted => role == Role.owner || role == Role.device;
}

Principal? principalOf(Request r) => r.context['principal'] as Principal?;

/// True when the caller may read private node data. In audit mode everyone
/// passes (and the miss is logged) so existing apps keep working until enforce.
bool trustedOrAudit(Request r) {
  final p = principalOf(r);
  if (p != null && p.isTrusted) return true;
  if (!gatewayEnforce) {
    print('AUTH-AUDIT would deny private access: ${r.method} /${r.url.path}');
    return true;
  }
  return false;
}

String hashSecret(String secret) => sha256.convert(utf8.encode(secret)).toString();

bool constantTimeEquals(String a, String b) {
  final x = utf8.encode(a), y = utf8.encode(b);
  var d = x.length ^ y.length;
  for (var i = 0; i < x.length && i < y.length; i++) {
    d |= x[i] ^ y[i];
  }
  return d == 0;
}

String _randomHex(int bytes) {
  final r = Random.secure();
  return List.generate(bytes, (_) => r.nextInt(256).toRadixString(16).padLeft(2, '0')).join();
}

String _b64u(List<int> b) => base64Url.encode(b).replaceAll('=', '');

class ViewerTokens {
  final List<int> _key;
  final Duration ttl;
  final DateTime Function() _now;

  ViewerTokens(List<int> key, {this.ttl = const Duration(hours: 1), DateTime Function()? now})
      : _key = key,
        _now = now ?? DateTime.now;

  /// Uses VIEWER_SIGNING_KEY when set, otherwise a random per-process key (tokens expire on restart).
  factory ViewerTokens.fromEnv() {
    final k = Platform.environment['VIEWER_SIGNING_KEY'];
    if (k != null && k.length >= 16) return ViewerTokens(utf8.encode(k));
    return ViewerTokens(List<int>.generate(32, (_) => Random.secure().nextInt(256)));
  }

  String _sig(String body) => _b64u(Hmac(sha256, _key).convert(utf8.encode(body)).bytes);

  String issue() {
    final exp = _now().toUtc().add(ttl).millisecondsSinceEpoch ~/ 1000;
    final body = 'gv1.$exp.${_randomHex(8)}';
    return '$body.${_sig(body)}';
  }

  bool verify(String token) {
    final parts = token.split('.');
    if (parts.length != 4 || parts[0] != 'gv1') return false;
    final exp = int.tryParse(parts[1]);
    if (exp == null) return false;
    if (!constantTimeEquals(parts[3], _sig('${parts[0]}.${parts[1]}.${parts[2]}'))) return false;
    return _now().toUtc().millisecondsSinceEpoch ~/ 1000 < exp;
  }
}

// ----------------------------------------------------------- device storage

class DeviceRow {
  final String id;
  final String name;
  final String secretSha256;
  final DateTime? lastSeenAt;
  final DateTime? revokedAt;
  const DeviceRow(this.id, this.name, this.secretSha256, this.lastSeenAt, this.revokedAt);
}

abstract class DeviceDirectory {
  Future<DeviceRow?> find(String id);
  Future<void> touch(String id);
  Future<void> create(String id, String name, String secretSha256);
  Future<bool> revoke(String id);
  Future<List<DeviceRow>> list();
  Future<bool> videoIsPublic(String videoId);
}

class PgDeviceDirectory implements DeviceDirectory {
  bool _ready = false;

  Future<Connection> _open() async {
    final c = await openDb();
    if (!_ready) {
      await c.execute("""
        CREATE TABLE IF NOT EXISTS gw_devices (
          id TEXT PRIMARY KEY,
          name TEXT NOT NULL,
          secret_sha256 TEXT NOT NULL,
          created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
          last_seen_at TIMESTAMPTZ,
          revoked_at TIMESTAMPTZ
        )""");
      _ready = true;
    }
    return c;
  }

  DeviceRow _row(ResultRow r) => DeviceRow(r[0].toString(), r[1].toString(), r[2].toString(), r[3] as DateTime?, r[4] as DateTime?);

  @override
  Future<DeviceRow?> find(String id) async {
    final c = await _open();
    try {
      final res = await c.execute(
        Sql.named('SELECT id, name, secret_sha256, last_seen_at, revoked_at FROM gw_devices WHERE id = @id'),
        parameters: {'id': id},
      );
      return res.isEmpty ? null : _row(res.first);
    } finally {
      await c.close();
    }
  }

  @override
  Future<void> touch(String id) async {
    final c = await _open();
    try {
      await c.execute(Sql.named('UPDATE gw_devices SET last_seen_at = now() WHERE id = @id'), parameters: {'id': id});
    } finally {
      await c.close();
    }
  }

  @override
  Future<void> create(String id, String name, String secretSha256) async {
    final c = await _open();
    try {
      await c.execute(
        Sql.named('INSERT INTO gw_devices (id, name, secret_sha256) VALUES (@id, @n, @h)'),
        parameters: {'id': id, 'n': name, 'h': secretSha256},
      );
    } finally {
      await c.close();
    }
  }

  @override
  Future<bool> revoke(String id) async {
    final c = await _open();
    try {
      final res = await c.execute(
        Sql.named('UPDATE gw_devices SET revoked_at = now() WHERE id = @id AND revoked_at IS NULL'),
        parameters: {'id': id},
      );
      return res.affectedRows > 0;
    } finally {
      await c.close();
    }
  }

  @override
  Future<List<DeviceRow>> list() async {
    final c = await _open();
    try {
      final res = await c.execute('SELECT id, name, secret_sha256, last_seen_at, revoked_at FROM gw_devices ORDER BY created_at DESC');
      return res.map(_row).toList();
    } finally {
      await c.close();
    }
  }

  @override
  Future<bool> videoIsPublic(String videoId) async {
    final c = await openDb();
    try {
      final res = await c.execute(
        Sql.named("SELECT COALESCE(visibility, 'public'), COALESCE(is_deleted, false) FROM mp_videos WHERE id = CAST(@v AS UUID) LIMIT 1"),
        parameters: {'v': videoId},
      );
      if (res.isEmpty) return false;
      return res.first[0].toString() == 'public' && res.first[1] != true;
    } finally {
      await c.close();
    }
  }
}

// -------------------------------------------------------------- route table

enum RouteClass { open, peer, viewer, device, owner }

final RegExp _viewerPath = RegExp(r'^/(player/video/(stream|thumbnail|stickers|stats)|watch|channel/(profile|videos))/[^/]+$');
final RegExp _videoScoped = RegExp(r'^/(?:player/video/(?:stream|thumbnail|stickers|stats)|watch)/([^/]+)$');
final RegExp _uuid = RegExp(r'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$');

/// Which kind of caller a route accepts. One table, so it is easy to audit.
///   open   - no token (landing page, viewer token issue, share links that check their own token)
///   peer   - other GupTik nodes (Trust Me); open until message signatures exist
///   viewer - read-only public player routes; an anonymous viewer token is enough
///   owner  - desktop owner token only
///   device - any paired phone or the desktop (everything else, including every write)
RouteClass classify(String method, String rawPath) {
  var m = method.toUpperCase();
  if (m == 'HEAD') m = 'GET';
  var p = rawPath.startsWith('/') ? rawPath : '/$rawPath';
  if (p.length > 1 && p.endsWith('/')) p = p.substring(0, p.length - 1);
  if (m == 'OPTIONS') return RouteClass.open;
  if (m == 'GET' && (p == '/' || p == '/web')) return RouteClass.open;
  if (m == 'POST' && p == '/viewer/token') return RouteClass.open;
  if (m == 'GET' && p.startsWith('/vault/files/')) return RouteClass.open;
  if (p.startsWith('/trustme/')) return RouteClass.peer;
  if (p == '/admin' || p.startsWith('/admin/')) return RouteClass.owner;
  if (m == 'GET' && _viewerPath.hasMatch(p)) return RouteClass.viewer;
  return RouteClass.device;
}

// --------------------------------------------------------------- auth store

class AuthStore {
  final String? ownerSha256;
  final ViewerTokens viewers;
  final DeviceDirectory directory;
  final Duration cacheTtl;
  final DateTime Function() _now;
  final Map<String, _Cached<DeviceRow?>> _devices = {};
  final Map<String, _Cached<bool>> _public = {};
  final Map<String, DateTime> _touched = {};

  AuthStore({
    required this.ownerSha256,
    required this.viewers,
    required this.directory,
    this.cacheTtl = const Duration(seconds: 30),
    DateTime Function()? now,
  }) : _now = now ?? DateTime.now;

  factory AuthStore.fromEnv() => AuthStore(
        ownerSha256: Platform.environment['OWNER_TOKEN_SHA256'],
        viewers: ViewerTokens.fromEnv(),
        directory: PgDeviceDirectory(),
      );

  Future<Principal?> authenticate(Request req) async {
    try {
      final h = req.headers['authorization'];
      var token = (h != null && h.toLowerCase().startsWith('bearer ')) ? h.substring(7).trim() : null;
      token ??= req.headers['x-viewer-token'] ?? req.url.queryParameters['vt'];
      if (token == null || token.isEmpty) return null;
      if (token.startsWith('gv1.')) {
        return viewers.verify(token) ? const Principal(Role.viewer, 'viewer', 'Viewer') : null;
      }
      final parts = token.split('.');
      if (parts.length != 3 || parts[0] != 'gt1') return null;
      final id = parts[1], hash = hashSecret(parts[2]);
      if (id == 'owner') {
        final o = ownerSha256;
        if (o != null && o.isNotEmpty && constantTimeEquals(hash, o)) return const Principal(Role.owner, 'owner', 'Desktop');
        return null;
      }
      final row = await _device(id);
      if (row == null || row.revokedAt != null || !constantTimeEquals(hash, row.secretSha256)) return null;
      _touchSoon(id);
      return Principal(Role.device, row.id, row.name);
    } catch (e) {
      print('AUTH error: $e');
      return null;
    }
  }

  Future<DeviceRow?> _device(String id) async {
    final c = _devices[id];
    if (c != null && _now().difference(c.at) < cacheTtl) return c.value;
    final row = await directory.find(id);
    _devices[id] = _Cached(row, _now());
    return row;
  }

  void _touchSoon(String id) {
    final last = _touched[id];
    if (last != null && _now().difference(last) < const Duration(minutes: 5)) return;
    _touched[id] = _now();
    directory.touch(id).catchError((_) {});
  }

  void forget(String id) => _devices.remove(id);

  Future<bool> videoIsPublic(String videoId) async {
    if (!_uuid.hasMatch(videoId)) return false;
    final c = _public[videoId];
    if (c != null && _now().difference(c.at) < cacheTtl) return c.value;
    final v = await directory.videoIsPublic(videoId);
    _public[videoId] = _Cached(v, _now());
    return v;
  }

  Future<String> createDevice(String name) async {
    final id = _randomHex(8);
    final secret = _b64u(List<int>.generate(32, (_) => Random.secure().nextInt(256)));
    await directory.create(id, name, hashSecret(secret));
    forget(id);
    return 'gt1.$id.$secret';
  }

  Future<bool> revokeDevice(String id) async {
    final ok = await directory.revoke(id);
    forget(id);
    return ok;
  }
}

class _Cached<T> {
  final T value;
  final DateTime at;
  _Cached(this.value, this.at);
}

// ---------------------------------------------------------------- middleware

Response _json(int code, Map<String, dynamic> body) =>
    Response(code, body: jsonEncode(body), headers: {'Content-Type': 'application/json'});

Middleware gatewayAuth(AuthStore store) => (Handler inner) => (Request req) async {
      final path = '/${req.url.path}';
      final cls = classify(req.method, path);
      final principal = await store.authenticate(req);
      req = req.change(context: {'principal': principal});

      var allowed = true;
      switch (cls) {
        case RouteClass.open:
        case RouteClass.peer:
          break;
        case RouteClass.viewer:
          allowed = principal != null;
          break;
        case RouteClass.device:
          allowed = principal != null && principal.isTrusted;
          break;
        case RouteClass.owner:
          allowed = principal != null && principal.role == Role.owner;
          break;
      }

      // Viewer tokens only ever see public, non-deleted videos (enforced in every mode).
      if (allowed && principal?.role == Role.viewer && cls == RouteClass.viewer) {
        final m = _videoScoped.firstMatch(path);
        if (m != null && !await store.videoIsPublic(m.group(1)!)) {
          return _json(404, {'error': 'not_found'});
        }
      }

      if (!allowed) {
        final who = principal == null ? 'anonymous' : '${principal.role.name}:${principal.id}';
        final ip = req.headers['cf-connecting-ip'] ?? req.headers['x-forwarded-for'] ?? 'direct';
        // Owner routes always enforce: they were never open and must not start open in audit mode.
        if (gatewayEnforce || cls == RouteClass.owner) {
          print('AUTH-DENY ${req.method} $path class=${cls.name} who=$who ip=$ip');
          return principal == null
              ? Response(401, body: jsonEncode({'error': 'unauthorized', 'hint': 'pair this device with your node'}), headers: {
                  'Content-Type': 'application/json',
                  'WWW-Authenticate': 'Bearer',
                })
              : _json(403, {'error': 'forbidden'});
        }
        print('AUTH-AUDIT would deny ${req.method} $path class=${cls.name} who=$who ip=$ip');
      }
      return inner(req);
    };

// -------------------------------------------------------------------- routes

final Map<String, List<DateTime>> _issueLog = {};

bool _issueAllowed(String ip, {int perMinute = 60}) {
  final now = DateTime.now();
  final l = _issueLog.putIfAbsent(ip, () => []);
  l.removeWhere((t) => now.difference(t) > const Duration(minutes: 1));
  if (l.length >= perMinute) return false;
  l.add(now);
  if (_issueLog.length > 5000) _issueLog.removeWhere((k, v) => v.isEmpty);
  return true;
}

/// POST /viewer/token (open, rate limited) and the owner-only /admin/devices routes.
void registerAuthRoutes(Router router, AuthStore store) {
  router.post('/viewer/token', (Request req) {
    final ip = req.headers['cf-connecting-ip'] ?? req.headers['x-forwarded-for'] ?? 'direct';
    if (!_issueAllowed(ip)) return _json(429, {'error': 'slow_down'});
    return _json(200, {'token': store.viewers.issue(), 'expires_in': store.viewers.ttl.inSeconds, 'scope': 'viewer'});
  });

  router.post('/admin/devices', (Request req) async {
    try {
      final data = jsonDecode(await req.readAsString());
      var name = (data is Map ? data['name'] : null)?.toString().trim() ?? '';
      if (name.isEmpty) name = 'Phone';
      if (name.length > 60) name = name.substring(0, 60);
      final token = await store.createDevice(name);
      return _json(200, {'id': token.split('.')[1], 'name': name, 'token': token});
    } catch (e) {
      return _json(400, {'error': 'bad_request'});
    }
  });

  router.get('/admin/devices', (Request req) async {
    final rows = await store.directory.list();
    return _json(200, {
      'devices': [
        for (final r in rows)
          {
            'id': r.id,
            'name': r.name,
            'last_seen_at': r.lastSeenAt?.toUtc().toIso8601String(),
            'revoked_at': r.revokedAt?.toUtc().toIso8601String(),
          }
      ]
    });
  });

  router.delete('/admin/devices/<id>', (Request req, String id) async {
    final ok = await store.revokeDevice(id);
    return ok ? _json(200, {'status': 'revoked'}) : _json(404, {'error': 'not_found'});
  });
}
''';
